import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side':..., 'price':..., 'qty':..., 'seq':...}
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def add_to_book(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def clean_top(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            if oid not in book or book[oid]['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return top
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            is_market = False
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            is_market = False
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
            is_market = True
        else:
            continue

        remaining = qty
        opposite_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            top = clean_top(opposite_heap)
            if top is None:
                break
            resting_id = top[2]
            resting = book[resting_id]
            resting_price = resting['price']

            if not is_market:
                if side == 'buy':
                    if resting_price > price:
                        break
                else:
                    if resting_price < price:
                        break

            trade_qty = min(remaining, resting['qty'])
            trade_price = resting_price

            if side == 'buy':
                trades.append([oid, resting_id, trade_price, trade_qty])
            else:
                trades.append([resting_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] <= 0:
                del book[resting_id]
                heapq.heappop(opposite_heap)
            # else leave it as top for next iteration check

        if typ == 'limit' and remaining > 0:
            add_to_book(oid, side, price, remaining, seq_counter)

        seq_counter += 1

    return trades

